import { defineChapterTopic, type ChapterAuthorSpec } from '../chapter-package-engine';
import type { EducationTopic } from '../education-types';

const NUTR_DISCLOSURE = {
  status: 'conceptual_diagram_only' as const,
  summary:
    'Delivered with quantitative nutrition calculations (Atwater 4-9-4 kcal/g, Harris–Benedict/Mifflin–St Jeor BMR, BMI, nitrogen balance), nutrient transport diagrams, and structured deficiency/clinical-nutrition cases.',
};

function makeNutrChapter(
  num: number,
  id: string,
  chapterTitle: string,
  title: string,
  summary: string,
  calcNote: string,
  comp: { colA: string; colB: string; rows: ChapterAuthorSpec['comparisonTable']['rows'] },
  mechanisms: string[],
  clinical: string,
  fmas: string[],
  sys: ChapterAuthorSpec['relatedSystems'],
  mcqs: ChapterAuthorSpec['selfChecks'],
): ChapterAuthorSpec {
  return {
    id,
    domainId: 'nutrition_health',
    chapterCode: `L${num}`,
    chapterOrder: num,
    chapterTitle,
    title,
    summary,
    targetTracks: ['school_foundations', 'secondary_premed', 'medical_foundations', 'allied_health'],
    curriculumMappings: [
      { frameworkId: 'pk_ncp_gs_4_8', gradeOrYear: 'Grades 6–8', unitOrModule: `Balanced Diet & Nutrients (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'pk_ncp_bio_9_12', gradeOrYear: 'Grades IX–XI', unitOrModule: `Nutrition & Digestion (${chapterTitle})`, status: 'elective' },
      { frameworkId: 'pk_pmdc_mbbs', gradeOrYear: 'MBBS Years 1–3', unitOrModule: `Biochemistry & Community Nutrition (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'in_cbse_bio_11_12', gradeOrYear: 'Class XI', unitOrModule: 'Digestion & Metabolic Nutrition', status: 'elective' },
    ],
    prerequisites: ['Biomolecule structures (Domain F)', 'GI mucosal digestion & portal drainage (A6, E10)'],
    learningObjectives: [
      `Quantify dietary energy equivalents, DRI/RDA benchmarks, and physiological utilization in ${chapterTitle.toLowerCase()}.`,
      `Trace luminal digestion, mucosal absorption, and systemic storage or deficiency pathology (${calcNote}).`,
      `Apply anthropometric, biochemical, and dietary calculations to nutritional cases across the human lifespan.`,
    ],
    depthExplanations: {
      school_foundations: `${summary} Balanced meals supply energy, building proteins, and protective vitamins/minerals so body organs grow and repair cleanly.`,
      secondary_premed: `${summary} Quantitative balance links kilocalorie intake, basal metabolic rate, and cofactor absorption across small intestinal villi.`,
      medical_foundations: `${mechanisms.join(' ')} Quantitative & clinical target: ${calcNote}.`,
      allied_health: `Dietary screening, anthropometry, dysphagia/enteral feeding tolerances, and micronutrient deficiency recognition in ${chapterTitle.toLowerCase()}: ${clinical}`,
    },
    keyConcepts: [
      { term: 'Nutritional Principle', definition: summary },
      { term: 'Quantitative Benchmark', definition: calcNote },
      { term: 'Clinical Deficiency / Excess', definition: clinical },
    ],
    keyFacts: [
      `Key calculation / benchmark: ${calcNote}.`,
      'Macronutrient Atwater factors: Carbohydrates = 4 kcal/g · Protein = 4 kcal/g · Lipids = 9 kcal/g · Ethanol = 7 kcal/g.',
    ],
    mechanisms,
    comparisonTable: { columnA: comp.colA, columnB: comp.colB, rows: comp.rows },
    misconceptions: [
      { misconception: 'Dietary vitamin pills are completely harmless at megadoses.', correction: 'Fat-soluble vitamins (especially A and D) accumulate in liver/adipose tissues causing hypervitaminosis toxicity (teratogenicity, pseudotumour cerebri, hypercalcaemia).' },
      { misconception: 'Refeeding a severely starved patient rapidly with high-carbohydrate calories immediately restores health.', correction: 'Abrupt carbohydrate feeding surges insulin, driving massive intracellular PO4³−, K+, and Mg2+ shifts that trigger fatal refeeding hypophosphataemia and cardiac/respiratory collapse.' },
    ],
    clinicalCorrelation: clinical,
    summaryParagraph: `${chapterTitle} unites dietary energetics, intestinal transport biology, and public-health deficiency prevention with explicit worked nutritional calculations.`,
    keyTakeaways: [
      mechanisms[0] ?? summary,
      calcNote,
      clinical,
    ],
    crossSubjectLinks: [
      { domainId: 'biochemistry', relation: 'Vitamins and trace minerals serve directly as enzymatic cofactors across central metabolism.' },
      { domainId: 'clinical_skills_public_health', relation: 'Population fortification (iodine, folate, vitamin D) prevents large-scale developmental morbidity.' },
    ],
    relatedSystems: sys,
    relatedFmaConceptIds: fmas,
    visualFormats: ['2d_diagram', 'structured_text', 'clinical_case'],
    diagram: {
      id: `diag-l${num}`,
      title: `${chapterTitle} — Intake → Absorption → Metabolic Balance`,
      kind: 'pathway',
      caption: `${summary} (${calcNote})`,
      disclaimer: 'Conceptual nutrition & metabolic balance diagram.',
      nodes: [
        { id: 'n1', label: 'Dietary Intake & Composition', sublabel: calcNote.slice(0, 62), tone: 'amber' },
        { id: 'n2', label: 'Digestion & Transport', sublabel: mechanisms[0]?.slice(0, 62) || summary.slice(0, 62), tone: 'teal' },
        { id: 'n3', label: 'Tissue Utilization / Imbalance', sublabel: clinical.slice(0, 62), tone: 'rose' },
      ],
      links: [
        { from: 'n1', to: 'n2', label: 'Enzymatic cleavage & epithelial carrier uptake' },
        { from: 'n2', to: 'n3', label: 'Deficiency, adequacy, or metabolic excess' },
      ],
    },
    assetDisclosure: NUTR_DISCLOSURE,
    activity: {
      title: `Nutritional Calculation & Case Lab (${chapterTitle})`,
      kind: 'calculation',
      prompt: `Solve the quantitative balance or clinical nutrition task for ${chapterTitle}: ${calcNote}. Verify intake vs physiological demand and identify red-flag deficiencies.`,
      keyTakeaway: clinical,
    },
    readingKeys: ['ap_ch24_nutrition', 'ap_ch23_digestive'],
    shortAnswers: [
      { id: `sa-l${num}-1`, prompt: `Perform or outline the core nutritional calculation / absorption mechanism in ${chapterTitle}.`, expectedPoints: [calcNote, mechanisms[0] ?? summary], modelAnswer: `${calcNote}. ${mechanisms.join(' ')}`, level: 'secondary_premed' },
      { id: `sa-l${num}-2`, prompt: `Contrast ${comp.colA} versus ${comp.colB}.`, expectedPoints: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator}`), modelAnswer: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator} (${r.clinicalOrFunctionalNote}).`).join(' '), level: 'medical_foundations' },
      { id: `sa-l${num}-3`, prompt: `Diagnose the key clinical consequence of deficiency or excess in ${chapterTitle.toLowerCase()}.`, expectedPoints: [clinical], modelAnswer: clinical, level: 'allied_health' },
    ],
    appliedCase: {
      id: `app-l${num}-1`,
      title: `Applied Nutritional Assessment Case: ${chapterTitle}`,
      scenario: `A community health and dietary case evaluates quantitative requirements and clinical findings in ${chapterTitle.toLowerCase()} (${calcNote}).`,
      questions: ['What quantitative intake or absorption step fails here?', 'Which clinical biomarker or dietary intervention corrects the imbalance safely?'],
      workedSolution: `${calcNote}. ${mechanisms[0]} Outcome: ${clinical}`,
      level: 'medical_foundations',
    },
    selfChecks: mcqs,
  };
}

